C5 independent fix — Local Settings Permission Power & Self-Mod Boundary.

**ONE — THE EXACT REQUEST (code change):**
```diff
--- a/src/policy/index.js
+++ b/src/policy/index.js
@@ -437,6 +437,27 @@ function selfModFragmentsForBase(baseDir) {
   ];
 }

+/**
+ * Regex patterns for detecting Claude Code settings files that carry permission rules.
+ * These files carry equal permission power and must all be gated by the self-mod rule.
+ * Pattern explanation:
+ * - Matches paths containing .claude/settings followed by optional dot-separated qualifiers and .json
+ * - Uses negative lookahead (?![a-z0-9_-]) to avoid matching .jsonx, .json.bak etc.
+ * - Handles Windows trailing dot (settings.local.json.) which resolves to the real file
+ * - Case-insensitive for cross-platform compatibility
+ */
+const CLAUDE_SETTINGS_FILE = /(^|[/\s\"=(])\.claude\/settings(?:\.[a-z0-9_-]+)*\.json(?![a-z0-9_-])/i;
+const MANAGED_SETTINGS_FILE = /(^|[/\s\"=(])managed-settings\.json(?![a-z0-9_-])/i;
+
+/**
+ * Check if a normalized path or command string references a Claude Code settings file
+ * that carries permission rules. This is the semantic classifier replacing the
+ * single hardcoded fragment match.
+ */
+function referencesClaudeSettings(norm) {
+  return CLAUDE_SETTINGS_FILE.test(norm) || MANAGED_SETTINGS_FILE.test(norm);
+}
+
 /**
  * Check whether an Edit/Write/NotebookEdit tool_input hits the self-mod rule.
  */
@@ -495,7 +516,24 @@ function isSelfModEdit(toolName, toolInput, baseDir) {
     }

   // Every script in bin/, not just the hooks.
-  if (/(?<![.\w])bin\/[^/]+\.(js|mjs|cjs|ps1|sh)$/.test(fp)) {
+  if (/(?<![.\w])bin\/[^/]+\.(js|mjs|cjs|ps1|sh)$/.test(fp)) {
     return true;
   }

   // Brace expansion splits a protected fragment across shell syntax:
   // `touch src/{policy,gate}/probe.js` writes into src/policy AND src/gate, but
   // the literal string contains neither `src/policy/` nor `src/gate/`
   // contiguously, so the substring checks below miss it (LOTOR-C2, found
   // 2026-08-21). Check the original command AND every comma-brace expansion of
   // it. This is STRICTLY ADDITIVE -- more strings to match, never fewer -- so it
   // can only gate MORE, never make the gate quieter. RESIDUAL, stated honestly:
   // sequence expansions ({1..9}, {a..z}) and anything past the variant cap are
   // not expanded; a protected fragment split only by those forms still slips.
   // 
   // C5: Local settings variants (LOTOR-C5) - check for Claude settings files
   // that carry permission rules. These files (.claude/settings.local.json,
   // managed-settings.json, etc.) carry equal permission power and must be gated.
+  if (referencesClaudeSettings(fp)) {
+    return true;
+  }

   const fragments = selfModFragmentsForBase(baseDir);
```

